namespace Touchline {
public class DarkComboBox : ThemeButton {
 public System.Collections.ArrayList Items=new System.Collections.ArrayList();
 public ComboBoxStyle DropDownStyle {get;set;}
 internal ContextMenuStrip ActiveMenu;
 int selected=-1; public event EventHandler SelectedIndexChanged;
 public int SelectedIndex {get{return selected;}set{if(selected==value)return;selected=value;Refresh();if(SelectedIndexChanged!=null)SelectedIndexChanged(this,EventArgs.Empty);}}
 public object SelectedItem {get{return selected>=0&&selected<Items.Count?Items[selected]:null;}set{SelectedIndex=Items.IndexOf(value);}}
 public DarkComboBox(){BackColor=MainForm.Card;ForeColor=MainForm.White;Height=34;TextAlign=ContentAlignment.MiddleLeft;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderColor=Color.FromArgb(43,58,77);}
 protected override void OnPaint(PaintEventArgs e){Text=L10n.T((SelectedItem==null?"请选择":Convert.ToString(SelectedItem)))+"  ▾";base.OnPaint(e);}
 protected override void OnClick(EventArgs e){base.OnClick(e);var menu=new ContextMenuStrip{BackColor=MainForm.Card,ForeColor=MainForm.White};for(int i=0;i<Items.Count;i++){int index=i;var item=new ToolStripMenuItem(L10n.T(Convert.ToString(Items[i]))){Checked=i==selected};item.Click+=(s,a)=>{SelectedIndex=index;};menu.Items.Add(item);}ActiveMenu=menu;menu.Closed+=(s,a)=>{var owner=FindForm();if(owner!=null&&!owner.IsDisposed&&owner.IsHandleCreated)owner.BeginInvoke((Action)(()=>menu.Dispose()));};menu.Show(this,new Point(0,Height));}
 protected override bool ProcessCmdKey(ref Message msg,Keys key){if(key==Keys.Down||key==Keys.Up){if(Items.Count>0)SelectedIndex=(selected+(key==Keys.Down?1:Items.Count-1)+Items.Count)%Items.Count;return true;}return base.ProcessCmdKey(ref msg,key);}
}
