 public static Button Button(string text,Action action){var b=new ThemeButton{Text=text,FlatStyle=FlatStyle.Flat,BackColor=Card,ForeColor=White,Font=new Font("Microsoft YaHei UI",10),Size=new Size(120,36),Margin=new Padding(5),Cursor=Cursors.Hand};b.FlatAppearance.BorderColor=Color.FromArgb(43,58,77);b.Click+=(s,e)=>{try{action();}catch(Exception ex){UiMessage.Show(ex.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}};return b;}
 static Label Label(string text,int size=11,Color? color=null){return new Label{BackColor=Color.Transparent,Text=text,AutoSize=true,ForeColor=color??White,Font=new Font("Microsoft YaHei UI",size),Margin=new Padding(8)};}
 Panel Section(string title){var p=new Panel{Dock=DockStyle.Top,BackColor=Card,Padding=new Padding(18),Height=160,Margin=new Padding(0,0,0,16)};p.Controls.Add(new Label{Text=title,Dock=DockStyle.Top,Height=34,Font=new Font("Microsoft YaHei UI",13,FontStyle.Bold)});return p;}
 void Navigate(string title){if(busy)return;if(game==null){if(title=="本地AI设置")OpenMenuSettings();return;}if(page==title)return;page=title;Render();}
 void DisposeWelcome(){foreach(var menu in body.Controls.OfType<MainMenuBackground>().ToArray())menu.Dispose();}
 void OpenMenuSettings(){if(game==null&&page=="本地AI设置"&&!body.Controls.OfType<MainMenuBackground>().Any())return;using(var redraw=new UiRedrawBatch(body)){DisposeWelcome();page="本地AI设置";heading.Text=page;subheading.Text="";SettingsPage();L10n.Watch(body);}}
 void Render(){if(game==null&&body.Controls.OfType<MainMenuBackground>().Any()){page="俱乐部总览";L10n.Protect(null);return;}using(var redraw=new UiRedrawBatch(body)){RenderContent();L10n.Watch(body);}}
 void RenderContent(){if(game!=null&&config.Enabled&&LocalRuntime.IsBundled(config.Endpoint,config.Model))LocalRuntime.Warmup(AppDomain.CurrentDomain.BaseDirectory);foreach(var item in nav.Controls.OfType<NavigationButton>())item.Selected=game!=null&&item.PageName==page;L10n.Protect(game);DisposeWelcome();body.Controls.Clear();advance.Enabled=game!=null&&!busy;advance.Text=game!=null&&game.Live!=null?"比赛推进10分钟":game!=null&&game.Phase!="常规赛"&&game.Phase!="欧冠资格赛"?"执行当前阶段":"推进赛程";
  if(game==null){page="俱乐部总览";heading.Text="欢迎来到触线";subheading.Text="掌控一家俱乐部，与29个本地智能体共同书写赛季。";Welcome();return;}
  var club=game.Club(game.PlayerClubId);heading.Text=page;subheading.Text=club.Name+"  /  联赛"+club.League+"  /  第"+game.Season+"赛季 · 第"+game.Week+"周  /  "+game.Phase+"  /  "+game.CareerMode;
  if(game.Live!=null&&page!="本地AI设置"){MatchPage();return;}
  switch(page){case "阵容与编队":SquadPage();break;case "理念与战术":TacticsPage();break;case "赛程与积分":SchedulePage();break;case "球员与转会":MarketPage();break;case "经营与荣誉":FinancePage();break;case "赛事统计":StatsPageSeparated();break;case "本地AI设置":SettingsPage();break;default:Dashboard();break;}
 }
