 void NewGame(){string seed=Ask("世界种子","输入整数；相同种子生成相同初始世界。",DateTime.Now.Ticks.ToString().Substring(10));int value;if(seed==null)return;if(!int.TryParse(seed,out value))throw new Exception("请输入整数种子。");string mode=ChooseCareerMode();if(mode==null)return;var g=GameFactory.New(value,false,mode);ChooseNewClub(g);}


 void Save(){if(game==null||busy)return;using(var dialog=new SaveFileDialog{Filter="触线存档|*.tmsave",InitialDirectory=Storage.Root,FileName="赛季"+game.Season+"_"+game.Club(game.PlayerClubId).Name}){Directory.CreateDirectory(Storage.Root);if(dialog.ShowDialog(this)!=DialogResult.OK)return;Storage.Save(game,dialog.FileName);savePath=dialog.FileName;status.Text="保存成功："+savePath;}}
 void LoadSave(){if(busy)return;Directory.CreateDirectory(Storage.Root);using(var dialog=new OpenFileDialog{Filter="触线存档及备份|*.tmsave;*.bak",InitialDirectory=Storage.Root}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;LoadGameFile(dialog.FileName);}}
 internal void LoadGameFile(string path){var loaded=Storage.Load(path);if(string.IsNullOrEmpty(loaded.PlayerClubId)){ChooseNewClub(loaded);return;}game=loaded;savePath=path;page="俱乐部总览";Render();}
 void CommitProgress(Game staged){game=Storage.Commit(staged,Path.Combine(Storage.Root,"autosave.tmsave"));}
 void AutoSave(){if(game!=null){Directory.CreateDirectory(Storage.Root);Storage.Save(game,Path.Combine(Storage.Root,"autosave.tmsave"));}}
 async void Run(Func<Game,Task> work){if(busy||game==null)return;busy=true;body.Enabled=false;nav.Enabled=false;running=new CancellationTokenSource();advance.Enabled=false;cancel.Visible=true;BeginProgressLog("推进赛程");try{Game staged=Storage.Clone(game);await Task.Run(async()=>await work(staged));Rules.Validate(staged);CommitProgress(staged);Progress("【已提交】操作完成，已自动存档。");}catch(OperationCanceledException){Progress("【已暂停】任务已取消；保留最近已保存检查点，之后未提交的处理已撤销。");}catch(Exception ex){Progress("【已暂停】保留最近已保存检查点，之后未提交的处理已撤销。原因："+ex.Message);UiMessage.Show(ex.Message,"操作暂停",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{busy=false;body.Enabled=true;nav.Enabled=true;cancel.Visible=false;running.Dispose();running=null;Render();}}
 void Progress(string s){if(IsDisposed||!IsHandleCreated)return;Action show=()=>{if(IsDisposed)return;status.Text=s;if(progressLog!=null&&!progressLog.IsDisposed)progressLog.Append(s);};if(InvokeRequired)BeginInvoke(show);else show();}
 FlowLayoutPanel Actions(){var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=54,WrapContents=false,AutoScroll=true};body.Controls.Add(p);return p;}
 DataGridView Grid(){var grid=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Bg,BorderStyle=BorderStyle.None,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells,RowHeadersVisible=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,EnableHeadersVisualStyles=false,GridColor=Color.FromArgb(40,52,70)};grid.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Card,ForeColor=Muted,Font=new Font(Font,FontStyle.Bold),Padding=new Padding(2)};grid.ColumnHeadersHeight=40;grid.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Bg,ForeColor=White,SelectionBackColor=Theme.Raised,SelectionForeColor=White,Padding=new Padding(2)};grid.AlternatingRowsDefaultCellStyle.BackColor=Card;grid.RowTemplate.Height=34;return grid;}
