 void Dashboard(){Club c=game.Club(game.PlayerClubId);var cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=114,WrapContents=false};body.Controls.Add(cards);Metric(cards,"资金",c.Funds.ToString("N0"),"整季工资 "+game.Squad(c.Id).Sum(p=>p.Value).ToString("N0"));Metric(cards,"阵容",game.Squad(c.Id).Count()+" 人","健康 "+game.Squad(c.Id).Count(p=>p.Injury==0));Metric(cards,"商业 / 荣誉",c.Commercial+" / "+c.Honor,"商业年收入 "+(c.Commercial*36));Metric(cards,"升级点",c.Upgrade.ToString(),"胜利积累 · 阵容训练");
  var panel=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1100,600),SplitterDistance=610,BackColor=Bg};body.Controls.Add(panel);panel.BringToFront();var news=new ListBox{Dock=DockStyle.Fill,BackColor=Card,ForeColor=White,BorderStyle=BorderStyle.None,HorizontalScrollbar=true,Font=new Font("Microsoft YaHei UI",10),ItemHeight=30};foreach(string s in game.News.Take(80))news.Items.Add(s);panel.Panel1.Controls.Add(news);var text=new TextBox{BackColor=Card,ForeColor=White,Multiline=true,ReadOnly=true,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,Font=new Font("Microsoft YaHei UI",12),ScrollBars=ScrollBars.Vertical};var next=game.Fixtures.Where(f=>!f.Played&&(f.Home==c.Id||f.Away==c.Id)).OrderBy(f=>f.Week).ThenBy(Competitions.Order).FirstOrDefault();text.Text="下一场比赛\r\n\r\n"+(next==null?"本赛季赛程已完成":game.Club(next.Home).Name+" vs "+game.Club(next.Away).Name+"\r\n"+next.Competition+" · 第"+next.Week+"周")+"\r\n\r\n当前阶段："+game.Phase+"\r\n\r\n"+PhaseHelp()+"\r\n\r\n理念："+c.Philosophy+"\r\n本场战术："+c.Tactic+"\r\n\r\n本地模型："+(config.Enabled?config.Model:"尚未启动，请先配置");text.Text+="\r\n\r\n"+"阵容预警\r\n"+PlayerAdvice.Warnings(game,c);panel.Panel2.Controls.Add(text);}
 void Metric(FlowLayoutPanel panel,string title,string value,string note){var p=new GradientPanel{Width=222,Height=96,BackColor=Card,EndColor=Theme.Raised,Margin=new Padding(0,0,12,12)};var a=Label(title,10,Muted);a.Location=new Point(14,8);p.Controls.Add(a);var b=Label(value,23,Accent);b.Location=new Point(12,27);p.Controls.Add(b);var c=Label(note,9,Muted);c.Location=new Point(14,72);p.Controls.Add(c);panel.Controls.Add(p);}
 string PhaseHelp(){switch(game.Phase){case "商业收入":return "第1步：先按旧商业价值×36转为资金。";case "成绩结算":return "第2步：结算排名、奖金、分成、商业价值、荣誉和统计奖项。";case "好感结算":return "第3步：按可出场比例更新好感，最高12。";case "欧冠资格赛":return "第4步：资格赛9队主客双循环，前3进欧冠，后6进欧联。";case "续约":return "第5步：到阵容页选择不续约的球员，再推进让其成为自由球员；其余29队由本地AI决定。";case "自主转会":return "第6步：球员自主意愿提出加盟申请，由玩家与本地AI回应。";case "需求转会":return "第7步：挂牌、报价、回应报价，点击推进执行一轮AI经营；在转会页手动关闭窗口。";case "工资结算":return "第8步：扣除全队身价总和的工资，资金可为负。";case "新赛季准备":return "开启新赛季，保留球员与俱乐部资产，重置本季统计。";default:return "推进会完成电脑球队比赛，并停在你的赛前。你的比赛按10分钟推进，中场可换人和调整战术。周末伤停-1、疲劳清零。";}}
 void SquadPage(){var actions=Actions();var chooser=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,DropDownStyle=ComboBoxStyle.DropDownList,Width=220};var clubs=game.Clubs.OrderBy(c=>c.League).ThenBy(c=>c.Name).ToArray();foreach(var c in clubs)chooser.Items.Add(c.Name);chooser.SelectedIndex=Array.FindIndex(clubs,c=>c.Id==game.PlayerClubId);actions.Controls.Add(chooser);var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1100,600),SplitterDistance=390};body.Controls.Add(split);split.BringToFront();var pitch=new PitchPanel{Dock=DockStyle.Fill};split.Panel1.Controls.Add(pitch);var grid=Grid();split.Panel2.Controls.Add(grid);
  Action draw=null;draw=()=>{grid.Rows.Clear();grid.Columns.Clear();Columns(grid,"球员","类型","脚","身价","好感","忠诚","伤停","疲劳","出场","可出场","红","绿","蓝","射／扑","续约","年龄","累计衰退");Club c=clubs[chooser.SelectedIndex];foreach(var p in game.Squad(c.Id)){int i=grid.Rows.Add(p.Name,p.Type,p.Foot==0?"双":p.Foot==1?"左":"右",p.Value.ToString("F1"),p.Favor,p.Loyalty,p.Injury,p.Fatigue,p.Appearances,p.AvailabilityKnown?p.Available.ToString():"待补录",p.Red,p.Green,p.Blue,p.Shot,p.Renew?"是":"否",game.CareerMode=="球星迭起"?p.Age.ToString():"—",game.CareerMode=="球星迭起"?p.DeclineCount.ToString():"—");grid.Rows[i].Tag=p.Id;grid.Rows[i].Cells[0].Style.BackColor=RoleColor(p.Type);grid.Rows[i].Cells[0].Style.ForeColor=p.Type=="门将"?Color.White:Color.Black;}pitch.Controls.Clear();for(int slot=0;slot<10;slot++){int s=slot;Player p=c.Lineup.Length==10?game.Players.FirstOrDefault(x=>x.Id==c.Lineup[s]):null;var b=Button((p==null?"选择球员":p.Name)+"\n"+Rules.Slots[s],()=>{if(c.Id!=game.PlayerClubId)throw new Exception("只能调整自己的球队。");Player selected=ChoosePlayer(game.Squad(c.Id).Where(x=>x.Injury==0),"选择 "+Rules.Slots[s]);if(selected==null)return;if(c.Lineup.Length!=10)c.Lineup=new string[10];int old=Array.IndexOf(c.Lineup,selected.Id);if(old>=0)c.Lineup[old]=c.Lineup[s];c.Lineup[s]=selected.Id;draw();});b.Size=new Size(112,52);int row=s==9?3:s/3;int col=s==9?1:s%3;b.Location=new Point(12+col*120,50+row*140);b.Font=new Font("Microsoft YaHei UI",8);b.BackColor=Color.FromArgb(28,62,58);pitch.Controls.Add(b);}};
  chooser.SelectedIndexChanged+=(s,e)=>draw();actions.Controls.Add(Button("阵容预警",()=>UiMessage.Show(PlayerAdvice.Warnings(game,game.Club(game.PlayerClubId)),"阵容预警")));actions.Controls.Add(Button("修改名字",()=>{string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id);string name=Ask("修改球员名字","输入新名字（1～30字，球员身份与统计保持不变）",p.Name);if(name==null)return;PlayerEditing.RenameOwn(game,p.Id,name);draw();AutoSave();}));actions.Controls.Add(Button("自动排阵",()=>{SquadTemplates.Auto(game,game.Club(game.PlayerClubId));draw();}));actions.Controls.Add(Button("训练升级",()=>{string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id);if(p.ClubId!=game.PlayerClubId)throw new Exception("不能训练外队球员。");string attr=Ask("训练属性","输入：红、绿、蓝、射门、黑。每次消耗1升级点。","红");int a=Array.IndexOf(new[]{"红","绿","蓝","射门","黑"},attr);if(a<0)return;SeasonFlow.Train(game,game.Club(game.PlayerClubId),p,a,1);draw();AutoSave();}));actions.Controls.Add(Button("不续约／续约",()=>{if(game.Phase!="续约")throw new Exception("仅续约阶段可操作。");string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id&&x.ClubId==game.PlayerClubId);p.Renew=!p.Renew;UiMessage.Show(p.Name+(p.Renew?"已确定续约":"已标记不续约，将在本阶段确认后离队"));}));actions.Controls.Add(Button("主动退役",()=>{string id=Selected(grid);if(id==null)return;var p=game.Players.First(x=>x.Id==id);if(p.ClubId!=game.PlayerClubId)throw new Exception("只能退役本队球员。");if(game.CareerMode!="球星迭起"||game.Phase!="续约")throw new Exception("主动退役仅在球星迭起模式的续约阶段开放。");if(UiMessage.Show("确定让"+p.Name+"退役？退役后不能重新签约。","办理退役",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;CareerCycle.Retire(game,p);draw();AutoSave();}));actions.Controls.Add(Button("补录可出场数",()=>{string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id);string text=Ask("历史数据补录",p.Name+"：扣除未在队及伤停后的可出场比赛数，不得小于"+p.Appearances,p.Appearances.ToString());int n;if(text==null)return;if(!int.TryParse(text,out n)||n<p.Appearances)throw new Exception("可出场数无效。");p.Available=n;p.AvailabilityKnown=true;draw();AutoSave();}));draw();}
 static Color RoleColor(string type){return type=="门将"?Color.FromArgb(0,112,192):type=="中场"?Color.FromArgb(146,208,80):type=="前锋"?Color.FromArgb(255,0,0):Color.FromArgb(0,176,240);}
 Player ChoosePlayer(IEnumerable<Player> pool,string title){var f=new Form{Text=title,Size=new Size(550,500),StartPosition=FormStartPosition.CenterParent,BackColor=Bg,ForeColor=White};var list=new ListBox{Dock=DockStyle.Fill,BackColor=Card,ForeColor=White,Font=Font};var ps=pool.ToArray();foreach(var p in ps)list.Items.Add(p.Name+" / "+p.Type+" / 身价"+p.Value+" / 脚"+p.Foot+" / 疲劳"+p.Fatigue);f.Controls.Add(list);Player result=null;var ok=Button("确认",()=>{if(list.SelectedIndex<0)return;result=ps[list.SelectedIndex];f.DialogResult=DialogResult.OK;});ok.Dock=DockStyle.Bottom;f.Controls.Add(ok);return f.ShowDialog(this)==DialogResult.OK?result:null;}
 void TacticsPage(){TacticsReferencePage();}
 static string TacticText(string t){return RuleDescriptions.Tactic.ContainsKey(t)?RuleDescriptions.Tactic[t]:"未知战术";}
 void SchedulePage(){var actions=Actions();var league=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,Width=160,DropDownStyle=ComboBoxStyle.DropDownList};league.Items.AddRange(new object[]{"联赛1","联赛2","联赛3","欧冠","欧联","欧冠资格赛","一级杯赛","二级杯赛"});league.SelectedIndex=game.Club(game.PlayerClubId).League-1;actions.Controls.Add(league);var groupSelect=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,Width=180,DropDownStyle=ComboBoxStyle.DropDownList};actions.Controls.Add(groupSelect);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,Size=new Size(1100,600),SplitterDistance=320};body.Controls.Add(split);split.BringToFront();var table=Grid();split.Panel1.Controls.Add(table);var fixtures=Grid();split.Panel2.Controls.Add(fixtures);Action draw=()=>{table.Rows.Clear();table.Columns.Clear();Columns(table,"排名","球队","比赛","积分","进球","失球","净胜");string label=Convert.ToString(league.SelectedItem);List<TableRow> rows;if(label.StartsWith("联赛"))rows=Competitions.League(game,league.SelectedIndex+1);else{var fs=game.Fixtures.Where(f=>f.Competition==label&&f.Stage=="小组"&&(groupSelect.SelectedItem==null||f.Group==Convert.ToString(groupSelect.SelectedItem))).ToArray();rows=Competitions.Table(game,fs.SelectMany(f=>new[]{f.Home,f.Away}).Distinct(),fs);}foreach(var r in rows)table.Rows.Add(r.Rank,r.Name,r.Played,r.Points,r.GF,r.GA,r.GD);fixtures.Rows.Clear();fixtures.Columns.Clear();Columns(fixtures,"周","赛事","阶段／组","主队","比分","客队");foreach(var f in game.Fixtures.Where(f=>label.StartsWith("联赛")?f.Competition=="联赛"&&game.Club(f.Home).League==league.SelectedIndex+1:f.Competition==label).OrderBy(f=>f.Week).ThenBy(f=>f.Group)){int i=fixtures.Rows.Add(f.Week,f.Competition,f.Stage+" "+f.Group,game.Club(f.Home).Name,f.Played?f.HomeGoals+" : "+f.AwayGoals:"—",game.Club(f.Away).Name);fixtures.Rows[i].Tag=f.Id;}};Action groups=()=>{groupSelect.Items.Clear();if(league.SelectedIndex>=3)foreach(string group in game.Fixtures.Where(f=>f.Competition==Convert.ToString(league.SelectedItem)&&f.Stage=="小组").Select(f=>f.Group).Distinct().OrderBy(x=>x))groupSelect.Items.Add(group);if(groupSelect.Items.Count>0)groupSelect.SelectedIndex=0;groupSelect.Visible=league.SelectedIndex>=3;};league.SelectedIndexChanged+=(s,e)=>{groups();draw();};groupSelect.SelectedIndexChanged+=(s,e)=>draw();groups();fixtures.CellDoubleClick+=(s,e)=>{string id=Selected(fixtures);if(id!=null)ShowMatchReview(game.Fixtures.First(f=>f.Id==id));};draw();}
 void MarketPage(){var actions=Actions();actions.Controls.Add(Label("本窗剩余报价："+Transfers.OffersRemaining(game,game.Club(game.PlayerClubId))+" / 5",10,Muted));var filter=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,Width=165,DropDownStyle=ComboBoxStyle.DropDownList};filter.Items.AddRange(new object[]{"货架与自由球员","所有球员","本队球员","待回应报价"});filter.SelectedIndex=0;actions.Controls.Add(filter);var grid=Grid();body.Controls.Add(grid);grid.BringToFront();Action draw=()=>{grid.Rows.Clear();grid.Columns.Clear();if(filter.SelectedIndex==3){Columns(grid,"球员","买方","卖方","费用","状态","类型");foreach(var o in game.Offers.OrderByDescending(x=>x.Status=="待回应")){Player p=game.Players.Concat(game.RetiredPlayers).First(x=>x.Id==o.PlayerId);int i=grid.Rows.Add(p.Name,game.Club(o.BuyerId).Name,o.SellerId==""?"自由球员":game.Club(o.SellerId).Name,o.Fee,o.Status,o.PlayerDriven?"自主":"需求");grid.Rows[i].Tag=o.Id;}return;}Columns(grid,"球员","俱乐部","位置","惯用脚","身价","参考费用","好感＋忠诚","伤停","挂牌","年龄");foreach(var p in game.Players.Where(p=>filter.SelectedIndex==1||filter.SelectedIndex==2&&p.ClubId==game.PlayerClubId||filter.SelectedIndex==0&&(p.Listed||p.ClubId=="")).OrderByDescending(p=>p.Value)){int i=grid.Rows.Add(p.Name,p.ClubId==""?"自由球员":game.Club(p.ClubId).Name,p.Type,p.Foot,p.Value,Transfers.Fee(game,p,false),p.Favor+p.Loyalty,p.Injury,p.Listed?"是":"否",game.CareerMode=="球星迭起"?p.Age.ToString():"—");grid.Rows[i].Tag=p.Id;}};filter.SelectedIndexChanged+=(s,e)=>draw();
  actions.Controls.Add(Button("挂牌／撤牌",()=>{if(game.Phase!="需求转会")throw new Exception("仅需求转会窗内可挂牌。");string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id&&x.ClubId==game.PlayerClubId);if(!p.Listed&&p.Type!="门将"&&game.Squad(p.ClubId).Count(x=>x.Type==p.Type)<=5)throw new Exception("该类型人数<=5，不能挂牌。");p.Listed=!p.Listed;draw();AutoSave();}));
  actions.Controls.Add(Button("提出报价",()=>{if(game.Phase!="需求转会")throw new Exception("仅需求转会阶段可以主动报价。");string id=Selected(grid);if(id==null)return;Player p=game.Players.First(x=>x.Id==id);double? quoted=AskTransferFee(p);if(!quoted.HasValue)return;double fee=quoted.Value;var o=Transfers.Offer(game,p,game.Club(game.PlayerClubId),fee);if(p.ClubId=="")Transfers.Complete(game,o,true);draw();AutoSave();}));
  actions.Controls.Add(Button("接受报价",()=>Respond(grid,true,draw)));actions.Controls.Add(Button("拒绝报价",()=>Respond(grid,false,draw)));
  actions.Controls.Add(Button("关闭转会窗",()=>{if(game.Phase!="需求转会")throw new Exception("当前不是需求转会窗。");if(game.Offers.Any(o=>o.Status=="待回应"&&(o.SellerId==game.PlayerClubId||o.BuyerId==game.PlayerClubId)))throw new Exception("请先回应涉及本队的待处理报价。");SeasonFlow.Advance(game);Render();AutoSave();}));draw();}
 void Respond(DataGridView grid,bool accept,Action draw){string id=Selected(grid);var o=game.Offers.FirstOrDefault(x=>x.Id==id);if(o==null)throw new Exception("请切换到待回应报价并选中一笔。");if(o.SellerId!=game.PlayerClubId&&!(o.PlayerDriven&&o.BuyerId==game.PlayerClubId))throw new Exception("只能回应本队负责的报价。");Transfers.Complete(game,o,accept);if(game.Phase=="自主转会"&&!game.Offers.Any(x=>x.PlayerDriven&&x.BuyerId==game.PlayerClubId&&x.Status=="待回应"))game.Phase="需求转会";draw();AutoSave();}
 void FinancePage(){var actions=Actions();actions.Controls.Add(Button("本队改名",RenameOwn));var grid=Grid();body.Controls.Add(grid);Columns(grid,"俱乐部","联赛","人数","总身价／季工资","资金","商业","商业收入","荣誉","升级点","再付工资后");foreach(var c in game.Clubs.OrderBy(c=>c.League).ThenByDescending(c=>c.Funds)){double wages=game.Squad(c.Id).Sum(p=>p.Value);grid.Rows.Add(c.Name,c.League,game.Squad(c.Id).Count(),wages.ToString("F2"),c.Funds.ToString("F2"),c.Commercial,c.Commercial*36,c.Honor,c.Upgrade,(c.Funds-wages).ToString("F2"));}}
 void StatsPage(){var actions=Actions();var comp=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,Width=180,DropDownStyle=ComboBoxStyle.DropDownList};comp.Items.AddRange(new object[]{"联赛","一级杯赛","二级杯赛","欧冠","欧联"});comp.SelectedIndex=0;actions.Controls.Add(comp);var metric=new DarkComboBox{BackColor=Card,ForeColor=White,FlatStyle=FlatStyle.Flat,Width=180,DropDownStyle=ComboBoxStyle.DropDownList};metric.Items.AddRange(new object[]{"进球","助攻","绝佳传球","抢夺球权","成功抢断","成功扑救"});metric.SelectedIndex=0;actions.Controls.Add(metric);var grid=Grid();body.Controls.Add(grid);grid.BringToFront();Action draw=()=>{grid.Rows.Clear();grid.Columns.Clear();Columns(grid,"名次","球员","俱乐部","联赛","位置","数据");string name=Convert.ToString(comp.SelectedItem);int index=metric.SelectedIndex,k=0;foreach(var p in game.Players.Where(p=>p.Stats.ContainsKey(name)).OrderByDescending(p=>p.Stats[name][index]))grid.Rows.Add(++k,p.Name,p.ClubId==""?"自由球员":game.Club(p.ClubId).Name,p.ClubId==""?0:game.Club(p.ClubId).League,p.Type,p.Stats[name][index]);};comp.SelectedIndexChanged+=(s,e)=>draw();metric.SelectedIndexChanged+=(s,e)=>draw();draw();}
