 var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1100,600),SplitterDistance=560,Panel1MinSize=360,Panel2MinSize=430};body.Controls.Add(split);split.BringToFront();var left=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,Size=new Size(560,600),SplitterDistance=430};split.Panel1.Controls.Add(left);matchPitch=new MatchPitch{Dock=DockStyle.Fill};matchPitch.SetMatch(game,m);left.Panel1.Controls.Add(matchPitch);matchEvents=new ListBox{Dock=DockStyle.Fill,BackColor=Card,ForeColor=White,BorderStyle=BorderStyle.None,HorizontalScrollbar=true,Font=Font};foreach(string e in m.Events.AsEnumerable().Reverse())matchEvents.Items.Add(L10n.T(e));left.Panel2.Controls.Add(matchEvents);MatchInformationPanel(split.Panel2);

