 void SettingsPage(){body.Controls.Clear();var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(16),AutoScroll=true};body.Controls.Add(flow);flow.Controls.Add(Label("真正的本地智能体",24,Accent));flow.Controls.Add(Label("模型仅访问本机。一般决定连续3次非法可接管；严格模型比赛保持暂停重试，连接失败不伪装成AI决策。",11,Muted));flow.Controls.Add(Label("本地地址"));var endpoint=new TextBox{BackColor=Card,ForeColor=White,Text=config.Endpoint,Width=620};flow.Controls.Add(endpoint);flow.Controls.Add(Label("模型名称"));var model=new TextBox{BackColor=Card,ForeColor=White,Text=config.Model,Width=380};flow.Controls.Add(model);var start=Button("启动内置本地模型",async()=>{try{status.Text="正在启动本地模型…";await LocalRuntime.Start(AppDomain.CurrentDomain.BaseDirectory,CancellationToken.None);config.Endpoint="http://127.0.0.1:17845/v1/chat/completions";config.Model="touchline-local";config.Enabled=true;config.TimeoutSeconds=180;Storage.SaveConfig(config);endpoint.Text=config.Endpoint;model.Text=config.Model;status.Text="离线模型已就绪。";}catch(Exception ex){UiMessage.Show(ex.Message);}});start.Size=new Size(260,45);flow.Controls.Add(start);flow.Controls.Add(Button("保存设置",()=>{LocalModelAgent.CheckEndpoint(endpoint.Text);config.Endpoint=endpoint.Text.Trim();config.Model=model.Text.Trim();config.Enabled=config.Model!="";Storage.SaveConfig(config);status.Text="本地AI设置已保存。";}));flow.Controls.Add(Button("打开诊断日志",()=>{System.IO.Directory.CreateDirectory(AiDiagnostics.DirectoryPath);System.Diagnostics.Process.Start(AiDiagnostics.DirectoryPath);}));flow.Controls.Add(Label("默认：Qwen2.5-1.5B-Instruct Q4_K_M；兼容CUDA环境优先GPU，否则CPU。\n更大的本地模型可替换为兼容的本机接口。模型质量、速度取决于机器配置。\nAI决定阵容、战术、换人、续约与报价；游戏规则只负责验证和执行。",11,Muted));}
 public static string Ask(string title,string prompt,string value){using(var f=new Form{Text=title,Size=new Size(560,205),StartPosition=FormStartPosition.CenterParent,BackColor=Bg,ForeColor=White,Font=new Font("Microsoft YaHei UI",10)}){var l=new Label{Text=prompt,Dock=DockStyle.Top,Height=65};f.Controls.Add(l);var t=new TextBox{BackColor=Card,ForeColor=White,Text=value,Location=new Point(18,72),Width=500};f.Controls.Add(t);var ok=Button("确定",()=>f.DialogResult=DialogResult.OK);ok.Location=new Point(390,110);f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog()==DialogResult.OK?t.Text:null;}}
