public class PitchPanel:Panel {
 public PitchPanel(){DoubleBuffered=true;BackColor=Color.FromArgb(20,62,53);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var pen=new Pen(Color.FromArgb(65,139,115),2)){int w=ClientSize.Width,h=ClientSize.Height;e.Graphics.DrawRectangle(pen,10,12,w-20,h-24);e.Graphics.DrawLine(pen,10,h/2,w-10,h/2);e.Graphics.DrawEllipse(pen,w/2-55,h/2-55,110,110);e.Graphics.DrawRectangle(pen,w/2-80,12,160,70);e.Graphics.DrawRectangle(pen,w/2-80,h-82,160,70);}}
}
}

